const PRINTED_LINES = ['解：设未知数为 x', '由题意列方程', '移项得'];

function charWidthEm(ch) {
  var code = ch.charCodeAt(0);
  if (code > 0x2e80) return 1.0;
  if (ch === ' ') return 0.28;
  if ('ilj.,:;\'!|'.indexOf(ch) >= 0) return 0.28;
  if ('mwMW'.indexOf(ch) >= 0) return 0.9;
  return 0.56;
}

function lineWidthEm(text) {
  var w = 0;
  for (var i = 0; i < text.length; i++) w += charWidthEm(text.charAt(i));
  return w;
}

const visual = {
  prepare: function (input) {
    return PRINTED_LINES.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var vw = input.viewport.widthDu;
    var vh = input.viewport.heightDu;
    var marginX = Math.max(16, vw * 0.08);
    var avail = Math.max(40, vw - marginX * 2);
    var maxEm = 0;
    for (var i = 0; i < PRINTED_LINES.length; i++) {
      maxEm = Math.max(maxEm, lineWidthEm(PRINTED_LINES[i]));
    }
    var baseFs = Math.max(10, Math.min(26, vh / 12));
    var fs = Math.min(baseFs, avail / Math.max(1, maxEm));
    var lineHeight = fs * 1.9;
    var blockWidth = maxEm * fs;
    var blockX = marginX + Math.max(0, (avail - blockWidth) / 2);
    var blockHeight = lineHeight * PRINTED_LINES.length;
    var topY = Math.max(fs * 1.2, (vh - blockHeight) / 2 + fs);
    var children = [];
    for (var j = 0; j < PRINTED_LINES.length; j++) {
      children.push({
        type: 'label',
        x: blockX,
        y: topY + j * lineHeight,
        text: PRINTED_LINES[j],
        fontSize: fs,
        textAnchor: 'start',
        fill: '#1b1b1b'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-transcription-erased-answer',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: vw, height: vh },
      paths: [],
      root: { type: 'group', children: children }
    };
  }
};
